"use client";
import { useEffect, useRef, useState, useTransition } from "react";
import { useRouter } from "next/navigation";
import { Search } from "lucide-react";
import styles from "./history.module.css";
const statuses = [
  ["", "All"],
  ["SENT", "Sent"],
  ["REPLIED", "Replied"],
  ["QUEUED", "Queued"],
  ["FAILED", "Failed"],
  ["CANCELLED", "Cancelled"],
] as const;
export function HistoryToolbar({
  q,
  status,
  campaign,
}: {
  q: string;
  status: string;
  campaign?: string;
}) {
  // Remount only when the confirmed URL changes, not when queue polling refreshes data.
  return (
    <Toolbar
      key={`${q}:${status}:${campaign ?? ""}`}
      q={q}
      status={status}
      campaign={campaign}
    />
  );
}
function Toolbar({
  q,
  status,
  campaign,
}: {
  q: string;
  status: string;
  campaign?: string;
}) {
  const router = useRouter();
  const [value, setValue] = useState(q);
  const [pending, start] = useTransition();
  const timer = useRef<ReturnType<typeof setTimeout> | undefined>(undefined);
  useEffect(() => () => clearTimeout(timer.current), []);
  function navigate(search: string, filter: string) {
    clearTimeout(timer.current);
    const params = new URLSearchParams();
    if (search) params.set("q", search);
    if (filter) params.set("status", filter);
    if (campaign) params.set("campaign", campaign);
    start(() =>
      router.push(`/history?${params.toString()}`, { scroll: false }),
    );
  }
  return (
    <form
      method="get"
      action="/history"
      className="flex items-center flex-wrap gap-3 mb-4"
      aria-busy={pending}
      onSubmit={(event) => {
        event.preventDefault();
        navigate(value, status);
      }}
    >
      {campaign && <input type="hidden" name="campaign" value={campaign} />}
      <input type="hidden" name="status" value={status} />
      <label
        className={`field-focus-wrapper ${styles.search} flex items-center gap-2.5 flex-1 min-w-55 h-11.5 py-0 px-4 [border:1px_solid_var(--h-border)] rounded-[var(--appearance-radius,_14px)] [background:var(--h-surface)] text-[var(--h-muted)] [@media(max-width:_859px)]:[flex-basis:100%] [@media(max-width:_859px)]:min-w-0`}
      >
        <Search size={18} aria-hidden="true" />
        <span className="sr-only">Search history</span>
        <input
          className="w-full min-w-0 h-full border-0 p-0 bg-transparent text-[var(--h-text)] shadow-[var(--appearance-shadow,none)] placeholder:text-[var(--h-muted)]"
          name="q"
          type="search"
          autoComplete="off"
          value={value}
          placeholder="Search recipients or companies…"
          onChange={(event) => {
            const next = event.target.value;
            setValue(next);
            clearTimeout(timer.current);
            timer.current = setTimeout(() => navigate(next, status), 250);
          }}
        />
      </label>
      <div
        className="flex flex-wrap gap-1.5"
        role="group"
        aria-label="Filter by status"
      >
        {statuses.map(([filter, label]) => (
          <button
            key={filter}
            type="button"
            className={`${styles.chip} py-2 px-3.5 [border:1px_solid_var(--h-border)] rounded-full text-[var(--h-muted)] text-[13px] font-semibold [background:var(--h-surface)] [&[aria-pressed='true']]:[background:var(--appearance-wash,_var(--color-history-h-border-12))] [&[aria-pressed='true']]:border-[var(--h-purple)] [&[aria-pressed='true']]:text-[var(--h-text)]`}
            aria-pressed={status === filter}
            onClick={() => navigate(value, filter)}
          >
            {label}
          </button>
        ))}
      </div>
    </form>
  );
}
